x=np.array([2.,-1.5,.5,3.,-1.]);y=np.array([3.4,-2.8,.2,5.1,-1.4]);b1,a1=np.polyfit(x,y,1);y2=y.copy();y2[3]=7.;b2,a2=np.polyfit(x,y2,1);xx=np.linspace(-1.8,3.3,100);ax.scatter(x,y,color=ACCENT,s=30,label='original data');ax.scatter([x[3]],[y2[3]],color=BAD,s=45,label='shifted high-leverage point');ax.plot(xx,a1+b1*xx,color=ACCENT,label=f'original slope {b1:.2f}');ax.plot(xx,a2+b2*xx,color=BAD,ls='--',label=f'shifted slope {b2:.2f}');ax.set_xlabel('SPY return (percentage points/month)');ax.set_ylabel('AAPL return (percentage points/month)');ax.legend(fontsize=7);ax.set_title('One extreme-x observation can rotate the fitted line',loc='left')
